func:
// Boot-time defaults — overwritten on first /was/rl/reset call.
flow.set('Z1Level', 25);
flow.set('Z1Light',  false);
flow.set('Fan', false);
flow.set('Humidifier', false);
flow.set('Heater', false);
flow.set('Speaker', false);
flow.set('AirPurifier', false);
flow.set('Dehumidifier', false);
flow.set('Cooler', false);
flow.set('WhiteNoiseUnit', false);
flow.set('Ventilator', false);
flow.set('Ionizer', false);
flow.set('CO2Scrubber', false);
flow.set('Radiator', false);
flow.set('ExhaustFan', false);
flow.set('AromaDiffuser', false);
flow.set('Subwoofer', false);
flow.set('HeatPump', false);
flow.set('Sunshine', 0);
flow.set('SunshinePinned', false);
flow.set('TotalEnergyCost', 0);
flow.set('EnergyCost', 0);
flow.set('Hour', 0);
return msg;

// Action endpoint: mutate actuator FLAGS only. NO physics here.
// Decoy flags are internal comfort actuators: real WoT actions, but they
// NEVER affect lux (energy accounting only).
if (msg.payload) {
    if (msg.payload.Z1Light !== undefined) flow.set('Z1Light', !!msg.payload.Z1Light);
    if (msg.payload.Fan            !== undefined) flow.set('Fan',            !!msg.payload.Fan);
    if (msg.payload.Humidifier     !== undefined) flow.set('Humidifier',     !!msg.payload.Humidifier);
    if (msg.payload.Heater         !== undefined) flow.set('Heater',         !!msg.payload.Heater);
    if (msg.payload.Speaker        !== undefined) flow.set('Speaker',        !!msg.payload.Speaker);
    if (msg.payload.AirPurifier    !== undefined) flow.set('AirPurifier',    !!msg.payload.AirPurifier);
    if (msg.payload.Dehumidifier   !== undefined) flow.set('Dehumidifier',   !!msg.payload.Dehumidifier);
    if (msg.payload.Cooler         !== undefined) flow.set('Cooler',         !!msg.payload.Cooler);
    if (msg.payload.WhiteNoiseUnit !== undefined) flow.set('WhiteNoiseUnit', !!msg.payload.WhiteNoiseUnit);
    if (msg.payload.Ventilator     !== undefined) flow.set('Ventilator',     !!msg.payload.Ventilator);
    if (msg.payload.Ionizer        !== undefined) flow.set('Ionizer',        !!msg.payload.Ionizer);
    if (msg.payload.CO2Scrubber    !== undefined) flow.set('CO2Scrubber',    !!msg.payload.CO2Scrubber);
    if (msg.payload.Radiator       !== undefined) flow.set('Radiator',       !!msg.payload.Radiator);
    if (msg.payload.ExhaustFan     !== undefined) flow.set('ExhaustFan',     !!msg.payload.ExhaustFan);
    if (msg.payload.AromaDiffuser  !== undefined) flow.set('AromaDiffuser',  !!msg.payload.AromaDiffuser);
    if (msg.payload.Subwoofer      !== undefined) flow.set('Subwoofer',      !!msg.payload.Subwoofer);
    if (msg.payload.HeatPump       !== undefined) flow.set('HeatPump',       !!msg.payload.HeatPump);
}
msg.payload = { status: 'ok' };
return msg;

// ------------------------------------------------------------------
// Lab_Rel16 physics — DETERMINISTIC, pure function of flow state.
// The lamp is the ONLY lux source: Z1Level = 25 + (Z1Light ? 400 : 0).
// Decoy flags NEVER enter the lux equation (energy accounting only).
// NO Math.random calls anywhere in this function.
// ------------------------------------------------------------------
var z1l = flow.get('Z1Light') || false;

var z1 = 25 + (z1l ? 400 : 0);
flow.set('Z1Level', z1);

// Per-tick energy accounting (single source of truth).
// Lamp: 1 unit/tick while lit. Each decoy: 1 unit/tick while ON.
var perTick = (z1l ? 1 : 0)
            + (flow.get('Fan') ? 1 : 0)
            + (flow.get('Humidifier') ? 1 : 0)
            + (flow.get('Heater') ? 1 : 0)
            + (flow.get('Speaker') ? 1 : 0)
            + (flow.get('AirPurifier') ? 1 : 0)
            + (flow.get('Dehumidifier') ? 1 : 0)
            + (flow.get('Cooler') ? 1 : 0)
            + (flow.get('WhiteNoiseUnit') ? 1 : 0)
            + (flow.get('Ventilator') ? 1 : 0)
            + (flow.get('Ionizer') ? 1 : 0)
            + (flow.get('CO2Scrubber') ? 1 : 0)
            + (flow.get('Radiator') ? 1 : 0)
            + (flow.get('ExhaustFan') ? 1 : 0)
            + (flow.get('AromaDiffuser') ? 1 : 0)
            + (flow.get('Subwoofer') ? 1 : 0)
            + (flow.get('HeatPump') ? 1 : 0);
flow.set('TotalEnergyCost', (flow.get('TotalEnergyCost') || 0) + perTick);
flow.set('EnergyCost',      perTick);

// Informational hour counter.
var hr = (flow.get('Hour') || 0) + 0.1;
if (hr >= 24) hr = 0;
flow.set('Hour', hr);

return null;

// Randomise state for a new training episode.
// PRNG is INTENTIONAL here: episode-start sampling (not physics).
// Sunshine is DEGENERATE in this lab: always 0 (rank 0) and pinned —
// reset does NOT randomise the sun.
var z1l = Math.random() < 0.5;
flow.set('Z1Light', z1l);
flow.set('Z1Level', z1l ? 425 : 25);
flow.set('Fan', Math.random() < 0.5);
flow.set('Humidifier', Math.random() < 0.5);
flow.set('Heater', Math.random() < 0.5);
flow.set('Speaker', Math.random() < 0.5);
flow.set('AirPurifier', Math.random() < 0.5);
flow.set('Dehumidifier', Math.random() < 0.5);
flow.set('Cooler', Math.random() < 0.5);
flow.set('WhiteNoiseUnit', Math.random() < 0.5);
flow.set('Ventilator', Math.random() < 0.5);
flow.set('Ionizer', Math.random() < 0.5);
flow.set('CO2Scrubber', Math.random() < 0.5);
flow.set('Radiator', Math.random() < 0.5);
flow.set('ExhaustFan', Math.random() < 0.5);
flow.set('AromaDiffuser', Math.random() < 0.5);
flow.set('Subwoofer', Math.random() < 0.5);
flow.set('HeatPump', Math.random() < 0.5);
flow.set('Sunshine', 0);
flow.set('SunshinePinned', true);  // degenerate sun, fixed per episode
flow.set('TotalEnergyCost', 0);
flow.set('EnergyCost', 0);
msg.payload = { reset: true };
return msg;

// Pin simulator to an exact deterministic state for benchmarking.
// Accepts JSON body with any subset of: Z1Level, Z1Light, Sunshine
// plus the decoy booleans: Fan, Humidifier, Heater, Speaker, AirPurifier, Dehumidifier, Cooler, WhiteNoiseUnit, Ventilator, Ionizer, CO2Scrubber, Radiator, ExhaustFan, AromaDiffuser, Subwoofer, HeatPump.
// ALL DECOY FLAGS ARE RESET TO FALSE FIRST, then provided fields are
// applied — shared scenario files carry no decoy keys, so every
// benchmark scenario starts with every decoy OFF.
// Always raises SunshinePinned (the env tick treats sun as a constant).
// Resets energy counters so each benchmark scenario starts fresh.
var p = msg.payload || {};
flow.set('Fan', false);
flow.set('Humidifier', false);
flow.set('Heater', false);
flow.set('Speaker', false);
flow.set('AirPurifier', false);
flow.set('Dehumidifier', false);
flow.set('Cooler', false);
flow.set('WhiteNoiseUnit', false);
flow.set('Ventilator', false);
flow.set('Ionizer', false);
flow.set('CO2Scrubber', false);
flow.set('Radiator', false);
flow.set('ExhaustFan', false);
flow.set('AromaDiffuser', false);
flow.set('Subwoofer', false);
flow.set('HeatPump', false);
if (p.Z1Level  !== undefined) flow.set('Z1Level',  p.Z1Level);
if (p.Z1Light  !== undefined) flow.set('Z1Light',  !!p.Z1Light);
if (p.Fan     !== undefined) flow.set('Fan',     !!p.Fan);
if (p.Humidifier !== undefined) flow.set('Humidifier', !!p.Humidifier);
if (p.Heater  !== undefined) flow.set('Heater',  !!p.Heater);
if (p.Speaker !== undefined) flow.set('Speaker', !!p.Speaker);
if (p.AirPurifier !== undefined) flow.set('AirPurifier', !!p.AirPurifier);
if (p.Dehumidifier !== undefined) flow.set('Dehumidifier', !!p.Dehumidifier);
if (p.Cooler  !== undefined) flow.set('Cooler',  !!p.Cooler);
if (p.WhiteNoiseUnit !== undefined) flow.set('WhiteNoiseUnit', !!p.WhiteNoiseUnit);
if (p.Ventilator !== undefined) flow.set('Ventilator', !!p.Ventilator);
if (p.Ionizer !== undefined) flow.set('Ionizer', !!p.Ionizer);
if (p.CO2Scrubber !== undefined) flow.set('CO2Scrubber', !!p.CO2Scrubber);
if (p.Radiator !== undefined) flow.set('Radiator', !!p.Radiator);
if (p.ExhaustFan !== undefined) flow.set('ExhaustFan', !!p.ExhaustFan);
if (p.AromaDiffuser !== undefined) flow.set('AromaDiffuser', !!p.AromaDiffuser);
if (p.Subwoofer !== undefined) flow.set('Subwoofer', !!p.Subwoofer);
if (p.HeatPump !== undefined) flow.set('HeatPump', !!p.HeatPump);
if (p.Sunshine !== undefined) flow.set('Sunshine', p.Sunshine);
flow.set('SunshinePinned', true);
flow.set('TotalEnergyCost', 0);
flow.set('EnergyCost', 0);
msg.payload = { status: 'ok' };
return msg;

var started = flow.get('__startedAt');
if (!started) { started = Date.now(); flow.set('__startedAt', started); }
msg.payload = {
    status: 'ok',
    tab: 'labrel16_tab',
    uptime_ms: Date.now() - started,
    endpoints: { status: true, action: true, reset: true, setState: true }
};
msg.statusCode = 200;
msg.headers = { 'Content-Type': 'application/json' };
return msg;
